  const rows=['......k.....k.......','......kk...kk.......','.......ggggg........','......ggggggg.......','.....kghhhhggk......','......hhhhhhh.......','......hkhkhhh.......','......hhhhhhh.......','.......hhhhh........','..wwww..aaa..wwww...','.wwwwwaaaaaaawwwww..','..wwwkaaaaaaakwww...','.....haaaa aaah.....','.....haaaaaaah......','......kkkkkk........','......gggggg........','......kkkkkk........','......gggggg........','......kkkkkk........','......kk..kk........','......kk..kk........','.....kkk..kkk.......'];
