 let world=null,selected=null;const actors=new Map(),positions=new Map(),origins=new Map();
 function render(w,focus,states={}){world=w;selected=focus;canvas.replaceChildren();actors.clear();positions.clear();origins.clear();
 const floors=sv('g',{},canvas),objects=sv('g',{},canvas),people=sv('g',{},canvas);
 for(const room of w.rooms){const{x,y,w:rw,d}=room;box(floors,x,y,rw,d,11,room.color,'#a99168','#8a7755');
 for(let xx=x;xx<x+rw;xx++)for(let yy=y;yy<y+d;yy++){const tile=polygon([point(xx,yy,11),point(xx+1,yy,11),point(xx+1,yy+1,11),point(xx,yy+1,11)],{fill:(xx+yy)%3===0?'#ffffff08':'#ffffff01',stroke:'#fff5df25','stroke-width':.8,'data-tile':xx+','+yy},floors);tile.addEventListener('click',()=>onTile(xx,yy));}
 if(y===0){box(floors,x,y,rw,.13,90,'#e8dcc0','#e7d8b5','#bba87e');for(let t=x+.8;t<x+rw-.8;t+=2)polygon([point(t,y+.14,81),point(t+1.1,y+.14,81),point(t+1.1,y+.14,37),point(t,y+.14,37)],{fill:'#b1c9c2',stroke:'#738d72','stroke-width':4},floors);}
 if(x===0)box(floors,x,y,.12,d,68,'#e6d5ae','#d7c298','#b39e75');
 const[a,b]=point(...room.label,12);label(a,b,room.name.toUpperCase(),floors,{class:'room-label','text-anchor':'middle'});}
 const items=[];for(const r of w.agents)items.push({z:r.homeX+r.homeY-.3,node:furniture({type:'finance-desk',x:r.homeX,y:r.homeY})});for(const o of w.objects){const n=furniture(o);if(o.type==='board'&&w.boardSummary){const[a,b]=point(o.x+1.1,o.y+.7);const c=w.boardSummary;label(a,b+28,(c.running||0)+(c.in_progress||0)+' en cours · '+(c.blocked||0)+' bloquées',n,{'text-anchor':'middle','font-size':9,fill:'#30423b'});}items.push({z:o.x+o.y,node:n});}items.sort((a,b)=>a.z-b.z).forEach(o=>objects.append(o.node));
 for(const r of w.agents.slice().sort((a,b)=>a.x+a.y-b.x-b.y)){const state=states[r.id]||'Conversation disponible',n=actor(r,state);people.append(n);actors.set(r.id,n);positions.set(r.id,[r.x,r.y]);origins.set(r.id,[r.x,r.y]);n.classList.toggle('selected',r.id===focus);n.querySelector('.agent-state').textContent=state;}
 }
 function position(id,x,y){const n=actors.get(id),old=origins.get(id);if(!n||!old)return;const a=point(...old),b=point(x,y);n.setAttribute('transform',`translate(${b[0]-a[0]} ${b[1]-a[1]})`);positions.set(id,[x,y]);}
